  if (set2 == NULL) {
    return inversion_list_clone(set1);
  }
  if (set1 == NULL) {
    return inversion_list_clone(set2);
  }

  unsigned int *buff =
      _get_buffer((set1->support + set2->support) * sizeof(unsigned int));
  if (!buff) {
    return NULL;
  }

  unsigned int j = 0;
  unsigned int i2 = 0;
  unsigned int cap = MAX(set1->capacity, set2->capacity);

